// R5 D14 exact joint-support Bellman census, budgets f=0..3.
// INPUT: window_adj.bin, generated by make_adj.py from frozen exact integer centers.
// Output: every original 14-label price-aware signature, with exact Bellman cost.
// Does not import previous class classification or DP certificates.
#include <bits/stdc++.h>
using namespace std;
constexpr int N=256,Q=101,K=14,FULL=(1<<K)-1;
constexpr int W[12]={0,16,32,48,1,64,17,80,18,24,34,82};
using Fam=vector<int>;
struct Action{int price; Fam masks;};
using Sig=vector<Action>;
Fam maximal(Fam a){
  sort(a.begin(),a.end()); a.erase(unique(a.begin(),a.end()),a.end());
  Fam out;
  for(int m:a){bool below=false;
    for(int t:a)if(t!=m&&(m&t)==m){below=true;break;}
    if(!below)out.push_back(m);
  }
  return out;
}
Sig signature(const vector<unsigned char>& adj,int u,int v){
  int labels[K]; copy(begin(W),end(W),labels); labels[12]=u; labels[13]=v;
  map<Fam,int> cheapest;
  for(int k=214;k<=314;k++){
    auto row=adj.data()+(size_t)(k-214)*N*N;
    Fam masks;
    for(int i=0;i<K;i++){
      int m=0;
      for(int j=0;j<K;j++)if(row[labels[i]*N+labels[j]])m|=(1<<j);
      masks.push_back(m);
    }
    auto fam=maximal(move(masks));
    if(fam.size()==1&&fam[0]==FULL)continue;
    if(!cheapest.count(fam))cheapest[fam]=k;
  }
  Sig sig;
  for(const auto& [fam,k]:cheapest)sig.push_back({k,fam});
  sort(sig.begin(),sig.end(),[](const auto&a,const auto&b){return a.price<b.price;});
  return sig;
}
string fingerprint(const Sig&sig){
  string s;
  for(const auto&a:sig){s+=to_string(a.price)+":";
    for(int m:a.masks)s+=to_string(m)+",";
    s+=";";
  }
  return s;
}
struct DP{
  int f;size_t states=0;uint64_t scale[K];
  unordered_map<uint64_t,int> memo;
  explicit DP(int budget):f(budget){scale[0]=1;
    for(int j=1;j<K;j++)scale[j]=scale[j-1]*10;
    memo.reserve(8000);
  }
  int V(uint64_t encoded,const Sig&sig){
    auto hit=memo.find(encoded);if(hit!=memo.end())return hit->second;
    int e[K],live=0;auto x=encoded;
    for(int j=0;j<K;j++){
      e[j]=x%10;x/=10;if(e[j]<=f)live|=1<<j;
    }
    if(__builtin_popcount((unsigned)live)<=1)return 0;
    int best=INT_MAX/4;
    for(const auto&a:sig){
      bool stalling=false;
      for(int m:a.masks)if((m&live)==live){stalling=true;break;}
      if(stalling)continue;
      int worst=0;
      for(int m:a.masks){
        uint64_t next=encoded;
        for(int j=0;j<K;j++)if(!(m&(1<<j))&&e[j]<=f)next+=scale[j];
        worst=max(worst,V(next,sig));
        if(a.price+worst>=best)break;
      }
      best=min(best,a.price+worst);
    }
    if(best==INT_MAX/4)throw runtime_error("no-progress-state");
    memo[encoded]=best; states++; return best;
  }
};
int main(int argc,char**argv){
  if(argc!=2){cerr<<"Usage: ./R5_D14_ALL_F0_F3 window_adj.bin\n";return 2;}
  vector<unsigned char> adj((size_t)Q*N*N);
  ifstream f(argv[1],ios::binary);
  f.read((char*)adj.data(),adj.size());
  if(f.gcount()!=(streamsize)adj.size())return 3;
  bool used[N]={};for(int i:W)used[i]=true;
  unordered_map<string,int> ids;
  vector<Sig> sigs;
  vector<pair<int,int>> pairs;
  vector<int> members;
  for(int u=0;u<N;u++)if(!used[u])for(int v=u+1;v<N;v++)if(!used[v]){
    auto a=signature(adj,u,v);auto key=fingerprint(a);
    auto it=ids.find(key);int id;
    if(it==ids.end()){
      id=(int)sigs.size();ids.emplace(move(key),id);
      sigs.push_back(move(a));pairs.push_back({u,v});members.push_back(0);
    }else id=it->second;
    members[id]++;
  }
  if(sigs.size()!=1906)throw runtime_error("signature-count-mismatch");
  if(accumulate(members.begin(),members.end(),0)!=29646)throw runtime_error("pair-count-mismatch");
  cout<<"class,u,v,members,actions,f,cost,nonterminal\n";
  long long checks=0,states=0;
  for(int id=0;id<(int)sigs.size();id++){
    for(int budget=0;budget<=3;budget++){
      DP dp(budget);int value=dp.V(0,sigs[id]);
      cout<<id<<","<<pairs[id].first<<","<<pairs[id].second<<","<<members[id]
          <<","<<sigs[id].size()<<","<<budget<<","<<value<<","<<dp.states<<"\n";
      if(value!=735+950*budget)throw runtime_error("unexpected-cost");
      checks++;states+=dp.states;
    }
  }
  cerr<<"PASS classes="<<sigs.size()<<" pairs=29646 checks="<<checks<<" nonterminal="<<states<<"\n";
}
